import { InternalServerErrorException } from '@nestjs/common';
import { CommandHandler, ICommandHandler } from '@nestjs/cqrs';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { CreatePickingOrderCommand } from '@/modules/order-management/picking-order/commands/create-picking-order.command';
import { PickingOrder } from '@/modules/order-management/picking-order/picking-order.entity';

@CommandHandler(CreatePickingOrderCommand)
export class CreatePickingOrderHandler
  implements ICommandHandler<CreatePickingOrderCommand>
{
  public constructor(
    @InjectRepository(PickingOrder)
    private readonly pickingOrderRepo: Repository<PickingOrder>,
  ) {}

  public async execute(
    command: CreatePickingOrderCommand,
  ): Promise<PickingOrder> {
    const { dto } = command;

    const entity = this.pickingOrderRepo.create({
      ...dto,
    });

    try {
      await this.pickingOrderRepo.insert(entity);
    } catch (error) {
      throw new InternalServerErrorException(
        `Picking order ${dto.pickingOrderId} at plant ${dto.plant} could not be created: ${error}`,
      );
    }

    return entity;
  }
}

