@CommandHandler(UpdatePickingOrderCommand)
export class UpdatePickingOrderHandler
  implements ICommandHandler<UpdatePickingOrderCommand>
{
  public constructor(
    @InjectRepository(PickingOrder)
    private readonly pickingOrderRepo: Repository<PickingOrder>,
  ) {}

  public async execute(
    command: UpdatePickingOrderCommand,
  ): Promise<PickingOrder> {
    const { plant, pickingOrderId, dto } = command;

    const entity = await this.pickingOrderRepo.findOne({
      where: { plant, pickingOrderId },
    });

    if (!entity) {
      throw new NotFoundException(
